#!/usr/bin/env python3
"""Builds the cmsg test: the conversion functions from husk-tl-bionic-net.c between a fixed head and tail."""
import sys
src = open(sys.argv[1]).read()
body = src[src.index('enum { G_SCM_RIGHTS = 1'):src.index('static long b_sendmsg(')]
HEAD = '\n#define _GNU_SOURCE\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stdbool.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <sys/socket.h>\nenum { G_SOL_SOCKET = 1 };\ntypedef struct { void *name; uint32_t namelen; struct iovec *iov; size_t iovlen; void *control; size_t controllen; int flags; } guest_msghdr;\n'
TAIL = 'static int fails; static void check(int ok, const char *w) { printf("%s %s\\n", ok ? "PASS" : "FAIL", w); if (!ok) fails++; }\nint main(void)\n{\n    int sv[2]; socketpair(AF_UNIX, SOCK_STREAM, 0, sv);\n    int p[2]; pipe(p); int q[2]; pipe(q);\n    /* a guest message carrying two descriptors, as Android\'s LocalSocket builds it (16-byte header) */\n    uint8_t gctl[64] = {0}; size_t l = 16 + 2 * sizeof(int); int lv = 1, ty = 1;\n    memcpy(gctl, &l, 8); memcpy(gctl + 8, &lv, 4); memcpy(gctl + 12, &ty, 4); memcpy(gctl + 16, &p[0], 4); memcpy(gctl + 20, &q[1], 4);\n    char byte = \'x\'; struct iovec iov = { &byte, 1 };\n    guest_msghdr gs = { NULL, 0, &iov, 1, gctl, 24, 0 };\n    socklen_t cl; void *ctl = cmsg_to_darwin(&gs, &cl);\n    struct msghdr m = {0}; m.msg_iov = &iov; m.msg_iovlen = 1; m.msg_control = ctl; m.msg_controllen = cl;\n    check(ctl && sendmsg(sv[0], &m, 0) == 1, "two descriptors converted and sent");\n    free(ctl);\n    /* received into a guest buffer with room for both */\n    uint8_t rctl[1024], gback[64]; char in = 0; struct iovec riov = { &in, 1 };\n    struct msghdr rm = {0}; rm.msg_iov = &riov; rm.msg_iovlen = 1; rm.msg_control = rctl; rm.msg_controllen = sizeof(gback);\n    guest_msghdr gr = { NULL, 0, &riov, 1, gback, sizeof(gback), 0 };\n    long r = recvmsg(sv[1], &rm, 0); int gf = 0; cmsg_from_darwin(&rm, &gr, &gf);\n    size_t gl; int glv, gty, f0, f1; memcpy(&gl, gback, 8); memcpy(&glv, gback + 8, 4); memcpy(&gty, gback + 12, 4); memcpy(&f0, gback + 16, 4); memcpy(&f1, gback + 20, 4);\n    check(r == 1 && gl == 24 && glv == 1 && gty == 1 && gr.controllen == 24 && gf == 0, "received as a guest SCM_RIGHTS message (16-byte header, length 24)");\n    write(q[1], "k", 1); char c = 0; read(f0 == p[0] ? q[0] : q[0], &c, 1);\n    check(fcntl(f0, F_GETFD) >= 0 && fcntl(f1, F_GETFD) >= 0 && f0 != p[0], "both descriptors arrive as new, open descriptors");\n    /* a guest buffer with room for one: the other is closed and MSG_CTRUNC reported */\n    ctl = cmsg_to_darwin(&gs, &cl); m.msg_control = ctl; m.msg_controllen = cl; sendmsg(sv[0], &m, 0); free(ctl);\n    uint8_t small[20]; guest_msghdr gr2 = { NULL, 0, &riov, 1, small, sizeof(small), 0 };\n    rm.msg_controllen = sizeof(small) + 16; long r2 = recvmsg(sv[1], &rm, 0); int gf2 = 0; cmsg_from_darwin(&rm, &gr2, &gf2);\n    size_t gl2; memcpy(&gl2, small, 8);\n    check(r2 == 1 && gl2 == 20 && (gf2 & 0x8) && gr2.controllen == 20, "too small: one descriptor kept, the rest closed, MSG_CTRUNC");\n    guest_msghdr none = { NULL, 0, &iov, 1, NULL, 0, 0 }; check(cmsg_to_darwin(&none, &cl) == NULL && cl == 0, "no control: nothing made");\n    uint8_t bad[24] = {0}; size_t bl = 999; memcpy(bad, &bl, 8); guest_msghdr gb = { NULL, 0, &iov, 1, bad, 24, 0 };\n    check(cmsg_to_darwin(&gb, &cl) == NULL, "a header longer than the buffer is not read past");\n    printf(fails ? "FAILED\\n" : "ALL PASSED\\n"); return fails != 0;\n}\n'
open(sys.argv[2], 'w').write(HEAD + body + TAIL)
